343	export interface DocumentReportState {
344	  document: DocumentFull | null;
345	  /** null => document not checked yet */
346	  violations: Violation[] | null;
347	  checkedAt: string | null;
348	  loading: boolean;
349	  checking: boolean;
350	  error: string | null;
351	}
