403	async function load(documentId: number): Promise<Partial<DocumentReportState>> {
404	  try {
405	    const report = await api.latestReport(documentId);
406	    return { document: report.document, violations: report.violations, checkedAt: report.checked_at };
407	  } catch (err) {
408	    if (!(err instanceof ApiError && err.status === 404)) throw err;
409	    return { document: await api.document(documentId) };
410	  }
411	}
