24	    24	async function send(path: string, init?: RequestInit): Promise<Response> {
25	    25	  const res = await fetch(BASE + path, init);
26	    26	  if (!res.ok) {
27	    27	    let message = res.statusText;
28	    28	    try {
29	    29	      const body = (await res.json()) as { detail?: unknown };
30	    30	      message = typeof body.detail === "string" ? body.detail : JSON.stringify(body.detail);
31	    31	    } catch {
32	    32	      /* non-JSON error body */
33	    33	    }
34	    34	    throw new ApiError(res.status, message);
35	    35	  }
36	    36	  return res;
37	    37	}
