863	   863	 * Reset by giving the owning component a new `key` per report.
864	   864	 */
865	   865	export function useViolationFilters(violations: readonly Violation[]) {
866	   866	  const [severities, setSeverities] = useState<ReadonlySet<Severity>>(ALL_SEVERITIES);
867	   867	  const [ruleId, setRuleId] = useState<number | null>(null);
868	   868	
869	   869	  const rules = useMemo(() => ruleOptions(violations), [violations]);
870	   870	  // A stale rule filter (rule no longer in this report) behaves like "all rules"
871	   871	  const effectiveRuleId = ruleId !== null && rules.some((r) => r.ruleId === ruleId) ? ruleId : null;
872	   872	
873	   873	  const counts = useMemo(
874	   874	    () => countBySeverity(filterViolations(violations, { severities: ALL_SEVERITIES, ruleId: effectiveRuleId })),
875	   875	    [violations, effectiveRuleId],
876	   876	  );
877	   877	  const visible = useMemo(
878	   878	    () => documentLevelFirst(filterViolations(violations, { severities, ruleId: effectiveRuleId })),
879	   879	    [violations, severities, effectiveRuleId],
880	   880	  );
881	   881	
882	   882	  const toggleSeverity = useCallback((s: Severity) => setSeverities((current) => toggle(current, s)), []);
883	   883	  const clear = useCallback(() => {
884	   884	    setSeverities(ALL_SEVERITIES);
885	   885	    setRuleId(null);
886	   886	  }, []);
887	   887	
888	   888	  const isFiltered = effectiveRuleId !== null || severities.size !== ALL_SEVERITIES.size;
889	   889	
890	   890	  return { severities, toggleSeverity, ruleId: effectiveRuleId, setRuleId, rules, counts, visible, isFiltered, clear };
891	   891	}
